package companion

// Dashboard structure follows the Management Center's telemetry-first layout,
// with metrics sourced from this companion's own usage database and plan state.
const dashboardChartScript = `<script>
window.__companionRegister('dashboard-chart', signal => {
  const chart = document.querySelector('.dash-chart');
  const tip = chart?.querySelector('.dash-chart-tooltip');
  if (!chart || !tip) return;
  const time = tip.querySelector('.dash-tooltip-time');
  const success = tip.querySelector('[data-count="success"]');
  const failed = tip.querySelector('[data-count="failed"]');
  const rate = tip.querySelector('.dash-tooltip-rate');
  function show(bar) {
    const ok = Number(bar.dataset.success);
    const bad = Number(bar.dataset.failed);
    time.textContent = bar.dataset.start + '–' + bar.dataset.end;
    success.textContent = String(ok);
    failed.textContent = String(bad);
    rate.textContent = ok + bad ? Math.round(ok * 100 / (ok + bad)) + '%' : '暂无请求';
    const center = bar.offsetLeft + bar.offsetWidth / 2;
    tip.style.left = Math.max(6, Math.min(center - tip.offsetWidth / 2, chart.clientWidth - tip.offsetWidth - 6)) + 'px';
    tip.classList.add('visible');
  }
  function hide() { tip.classList.remove('visible'); }
  chart.querySelectorAll('.dash-bar-col').forEach(bar => {
    bar.addEventListener('pointerenter', () => show(bar), {signal});
    bar.addEventListener('focus', () => show(bar), {signal});
    bar.addEventListener('click', () => show(bar), {signal});
  });
  chart.addEventListener('pointerleave', hide, {signal});
  chart.addEventListener('focusout', event => {
    if (!chart.contains(event.relatedTarget)) hide();
  }, {signal});
});
</script>`

const usageDashboardTemplate = `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>仪表盘 · CPA Companion</title>` + stylesheetLink + `</head><body><div class="shell"><aside class="sidebar"><a class="brand" href="/dashboard"><img class="brand-mark" src="/assets/logo.png" width="30" height="30" alt=""><span class="brand-copy"><span class="brand-title">CPA Companion</span>` + brandVersionTemplate + `</span></a><nav class="nav"><span class="nav-label">工作台</span><a class="nav-link active" aria-current="page" href="/dashboard">仪表盘</a><a class="nav-link" href="/keys">我的密钥</a>{{if .Admin}}<a class="nav-link" href="/admin">分流方案</a><a class="nav-link" href="/audit">内容审计</a>{{end}}<a class="nav-link" href="/prices">模型价格</a><a class="nav-link" href="/logs">使用日志</a></nav>` + sidebarGitHubTemplate + `<div class="sidebar-footer"><div class="identity"><span class="avatar"><span class="avatar-fallback">C</span>{{if .User.AvatarURL}}<img src="{{.User.AvatarURL}}" alt="" referrerpolicy="no-referrer">{{end}}</span><span class="identity-copy"><span class="identity-name">{{.User.Username}}</span><span class="identity-meta">{{.User.ID}}</span></span></div><form method="post" action="/auth/logout"><input type="hidden" name="csrf" value="{{.CSRF}}"><button class="logout">退出登录</button></form></div></aside><main class="content"><div class="content-inner"><div class="dashboard-page">
<section class="dash-hero"><div class="dash-hero-copy"><h1>{{.Verdict}}<span class="dash-period">。</span></h1><p class="dash-hero-meta">CPA COMPANION · {{.ScopeText}} · 北京时间</p><p class="dash-hero-desc">实时掌握 API 请求、上游账号和分流方案的运行状态。</p><div class="dash-actions"><a class="dash-primary" href="/keys">管理我的密钥</a><a class="dash-quiet-link" href="/logs">查看使用日志 →</a></div></div><div class="dash-hero-panel"><div class="dash-hero-panel-top"><span class="dash-overline">统计请求</span><span class="dash-live">LIVE</span></div><strong class="dash-figure">{{.RecentRequests}}</strong><span class="dash-window">最近 6 小时 · 10 分钟粒度</span><div class="dash-ratio" aria-hidden="true"><span class="ok" style="width:{{.SuccessWidth}}%"></span><span class="bad" style="width:{{.FailureWidth}}%"></span></div><div class="dash-split"><span><i class="dash-dot"></i>成功 <b>{{.RecentSuccess}}</b></span><span><i class="dash-dot bad"></i>失败 <b>{{.RecentFailure}}</b></span></div></div><svg class="dash-wire" viewBox="0 0 100 28" preserveAspectRatio="none" role="img" aria-label="最近六小时请求趋势"><polyline points="{{.WirePoints}}"></polyline></svg></section>
<div class="dash-controls"><span class="dash-scope">以下用量指标：最近 6 小时 · {{.ScopeText}}</span>{{if .Admin}}<div class="dash-tabs"><a href="/dashboard" class="{{if not .All}}active{{end}}">我的数据</a><a href="/dashboard?scope=all" class="{{if .All}}active{{end}}">全部用户</a></div>{{end}}</div>
<section class="dash-stats" aria-label="运行指标"><article class="dash-stat green"><span class="dash-stat-label">成功率</span><strong class="dash-stat-value">{{.SuccessRate}}%</strong><div class="dash-meter" aria-hidden="true"><span style="width:{{.SuccessRate}}%"></span></div><span class="dash-stat-hint">最近 6 小时 · 本地 429 不计入</span></article><article class="dash-stat"><span class="dash-stat-label">分配的上游账号</span><strong class="dash-stat-value">{{.Assigned}}</strong><div class="dash-meter" aria-hidden="true"><span style="width:{{.ActivePercent}}%"></span></div><span class="dash-stat-hint">当前可用 {{.ActiveAccounts}} 个</span></article><article class="dash-stat"><span class="dash-stat-label">我的 API Key</span><strong class="dash-stat-value">{{.KeyCount}}</strong><span class="dash-stat-hint">由当前账号创建和管理</span></article><article class="dash-stat"><span class="dash-stat-label">已使用模型</span><strong class="dash-stat-value">{{.ModelCount}}</strong><span class="dash-stat-hint">当前统计范围内的不同模型</span></article></section>
<section class="dash-section"><header class="dash-section-head"><span class="dash-eyebrow">实时流量</span><h2>请求吞吐</h2><p>最近 6 小时，以 10 分钟为粒度；绿色为成功，红色为失败。本地 429 不计入。</p></header><div class="dash-panel"><div class="dash-chart-legend"><span><i class="dash-dot"></i>成功 <b>{{.RecentSuccess}}</b></span><span><i class="dash-dot bad"></i>失败 <b>{{.RecentFailure}}</b></span></div><div class="dash-chart" role="group" aria-label="最近六小时每十分钟请求成功与失败数量">{{range .Traffic}}<div class="dash-bar-col" tabindex="0" aria-label="{{.Label}} 至 {{.EndLabel}}，成功 {{.Success}}，失败 {{.Failed}}" data-start="{{.Label}}" data-end="{{.EndLabel}}" data-success="{{.Success}}" data-failed="{{.Failed}}"><div class="dash-bar-stack" aria-hidden="true"><span style="height:{{.SuccessHeight}}%"></span><span class="fail" style="height:{{.FailedHeight}}%"></span></div></div>{{end}}{{if not .RecentRequests}}<div class="dash-chart-empty">暂无请求，流量会在这里出现。</div>{{end}}<div class="dash-chart-tooltip" aria-hidden="true"><strong class="dash-tooltip-time"></strong><div class="dash-tooltip-row"><i class="dash-dot"></i><span>成功</span><b data-count="success"></b></div><div class="dash-tooltip-row"><i class="dash-dot bad"></i><span>失败</span><b data-count="failed"></b></div><span class="dash-tooltip-rate"></span></div></div><div class="dash-axis"><span>{{(index .Traffic 0).Label}}</span><span>{{(index .Traffic 18).Label}}</span><span>{{(index .Traffic 36).Label}}</span></div></div></section>
<section class="dash-section"><header class="dash-section-head"><span class="dash-eyebrow">上游</span><h2>供应商对比</h2><p>按最近 6 小时请求量排序；账号数来自当前 CPA 账号目录。</p></header><div class="dash-panel">{{if .Providers}}<ol class="dash-fleet">{{range $index,$provider := .Providers}}<li><span class="dash-rank">{{if lt $provider.Rank 10}}0{{end}}{{$provider.Rank}}</span><div><strong class="dash-provider-name">{{$provider.Name}}</strong><span class="dash-provider-meta">{{$provider.Accounts}} 个账号</span></div><svg class="dash-spark" viewBox="0 0 100 28" preserveAspectRatio="none" aria-hidden="true"><polyline points="{{$provider.Points}}"></polyline></svg><div class="dash-fleet-number"><b>{{$provider.Requests}}</b><small>次请求</small></div><div class="dash-fleet-rate"><b>{{$provider.Rate}}%</b><div class="dash-meter"><span style="width:{{$provider.Rate}}%"></span></div></div></li>{{end}}</ol>{{else}}<div class="dash-empty">暂无上游账号信息。</div>{{end}}</div></section>
<section class="dash-details"><div class="dash-panel"><header class="dash-detail-head"><span class="dash-eyebrow">健康度</span><h2>上游账号状态</h2></header><div class="dash-health-bar" aria-hidden="true"><span class="good" style="width:{{.ActivePercent}}%"></span><span class="quiet" style="width:{{.InactivePercent}}%"></span></div><div class="dash-health-legend"><span><i class="dash-dot"></i> 可用 <b>{{.ActiveAccounts}}</b></span><span><i class="dash-dot" style="background:var(--dash-amber)"></i> 暂不可用 <b>{{.InactiveAccounts}}</b></span></div><dl class="dash-spec"><div><dt>已分配账号</dt><dd>{{.Assigned}} 个</dd></div><div><dt>当前可用账号</dt><dd>{{.ActiveAccounts}} 个</dd></div></dl><a class="dash-detail-link" href="/keys">查看我的账号 →</a></div><div class="dash-panel"><header class="dash-detail-head"><span class="dash-eyebrow">运行时</span><h2>使用概况</h2></header><dl class="dash-spec"><div><dt>统计范围</dt><dd>最近 6 小时 · {{.ScopeText}}</dd></div><div><dt>输入 Token</dt><dd>{{.Summary.InputTokens}}</dd></div><div><dt>输出 Token</dt><dd>{{.Summary.OutputTokens}}</dd></div><div><dt>预估费用</dt><dd>${{.Summary.CostUSD}}</dd></div>{{if .HasBudget}}<div><dt>方案累计额度</dt><dd>${{.Used}} / ${{.Budget}}</dd></div>{{end}}</dl><a class="dash-detail-link" href="/logs">查看请求明细 →</a></div></section>
<section class="dash-section" aria-labelledby="dash-plan-title"><header class="dash-section-head"><span class="dash-eyebrow">我的分配</span><h2 id="dash-plan-title">已分配方案情况</h2><p>显示当前登录账号的分流方案；用量视图切换不影响此处。</p></header><div class="dash-panel dash-plan"><div><div class="dash-plan-head"><div><span class="dash-overline">当前方案</span>{{if .HasPlan}}<strong class="dash-plan-name">{{.PlanName}}</strong>{{else}}<strong class="dash-plan-name">尚未分配</strong>{{end}}</div><span class="dash-plan-status {{.PlanStatusClass}}">{{.PlanStatus}}</span></div>{{if .HasPlan}}<span class="dash-overline">可用时段 · 北京时间</span><div class="dash-plan-periods">{{range .PlanPeriods}}<span>{{.}}</span>{{else}}<span>暂无可用时段</span>{{end}}</div><div class="dash-plan-metrics"><div class="dash-plan-metric"><span>每分钟请求数</span><strong>{{if .Plan.RPM}}{{.Plan.RPM}} RPM{{else}}不限制{{end}}</strong></div><div class="dash-plan-metric"><span>使用额度</span><strong>{{if .HasBudget}}${{.Used}} / ${{.Budget}}{{else}}不限制{{end}}</strong></div></div>{{else}}<p class="dash-plan-empty">当前账号还没有分配分流方案，分配后会在这里显示可用时段和使用限制。</p>{{end}}<a class="dash-detail-link" href="/keys">查看我的密钥与额度 →</a></div><div><span class="dash-overline">已分配上游 · {{.Assigned}} 个</span>{{if .PlanAccounts}}<ul class="dash-plan-account-list">{{range .PlanAccounts}}<li><i class="{{if .Cooling}}cooling{{else if .Active}}active{{end}}" aria-hidden="true"></i><div><strong>{{.Label}}</strong><small>{{.Period}}</small></div><em>{{.State}}</em></li>{{end}}</ul>{{else}}<p class="dash-plan-empty">暂无已分配的上游账号。</p>{{end}}</div></div></section>
<section class="dash-section" aria-labelledby="dash-assignments-title"><header class="dash-section-head dash-assignments-head"><div><span class="dash-eyebrow">公开分配</span><h2 id="dash-assignments-title">所有用户的方案分配</h2><p>所有已登录用户可查看；按用户展示方案和已分配上游。</p></div><span class="dash-assignments-count">已分配 {{.AssignedUsers}} / {{len .Assignments}} 位用户</span></header><div class="dash-panel"><ul class="dash-public-list">{{range .Assignments}}<li class="dash-public-row"><div><div class="dash-public-title"><div class="dash-public-user"><strong>{{.Username}}</strong><small>ID {{.UserID}}</small></div><span class="dash-assignment-status {{.StatusClass}}">{{.Status}}</span></div><div class="dash-public-plan">分流方案<strong>{{.PlanName}}</strong></div><div class="dash-public-period"><span>方案可用时段 · 北京时间</span>{{if .Periods}}{{.Periods}}{{else}}—{{end}}</div></div><div><span class="dash-overline">已分配上游 · {{.AccountCount}} 个</span>{{if .Accounts}}<ul class="dash-plan-account-list">{{range .Accounts}}<li><i class="{{if .Cooling}}cooling{{else if .Active}}active{{end}}" aria-hidden="true"></i><div><strong>{{.Label}}</strong><small>{{.Period}}</small></div><em>{{.State}}</em></li>{{end}}</ul>{{else}}<p class="dash-plan-empty">暂无已分配的上游账号。</p>{{end}}</div></li>{{else}}<li class="dash-empty">暂无用户分配信息。</li>{{end}}</ul></div></section>
<section class="dash-section"><header class="dash-section-head"><span class="dash-eyebrow">下一步</span><h2>接下来去哪里</h2></header><div class="dash-next"><a href="/keys"><i>↗</i><strong>我的密钥</strong><span>复制或轮换 API Key，查看分配的上游。</span></a>{{if .Admin}}<a href="/admin"><i>↗</i><strong>分流方案</strong><span>管理方案、上游账号与可用时间。</span></a>{{end}}<a href="/prices"><i>↗</i><strong>模型价格</strong><span>查看模型计费表达式与费用规则。</span></a><a href="/logs"><i>↗</i><strong>使用日志</strong><span>按模型、状态和时间检索请求。</span></a></div></section><p class="dash-note">请求与费用统计从启用 SQL 日志后开始；价格按请求完成时的配置记录，历史请求不会回填。</p>
</div></div></main></div>` + moduleBootstrapScript + dashboardChartScript + navigationScript + `</body></html>`
